add('model-sticking',6,'Figure 10 discussion','author_interpretation','Data agree approximately with the model but skew toward larger average volume in the middle of the distribution. Authors interpret this as sticking probability below 1 as ligands passivate particles, eventually approaching zero for stability. No fitted numerical probability or time dependence is supplied.')
add('fig8a',6,'Figure 8a main image and caption','tem_figure','Ir nanocrystals capped with C6F13C2H4SH; main scale bar 10 nm. The sole described Ir condition family is at 3.3 mM, 7.6:1, 80 °C, 276 bar. No author-assigned batch or numerical mean diameter is supplied.')
