for n in range(1,49):
    m=re.search(r'\('+str(n)+r'\)\s+(.*?)(?=\('+str(n+1)+r'\)\s|\Z)',reftext,re.S)
    assert m,n
    citation=re.sub(r'\s+',' ',m.group(1)).strip()
    if n==48:citation=citation.split('9440 J. Phys.')[0].strip()
    add(f'reference-{n:02}',8,f'References and Notes, item {n}','reference_or_note',citation,disposition='bibliographic_context_not_independently_read_in_this_source_review',reference_number=n)
add('note22-context',8,'Reference/Note 22','cited_synthesis_context','The note describes silicon nanowires in supercritical hexane at 500 °C using gold seed crystals stabilized by thiol ligands, citing Holmes et al., Science 2000, 287, 1471. This does not add a current silicon recipe or transfer 500 °C to the Ag/Ir/Pt reactions.',disposition='retain_cited_context_only')
add('note32-context',8,'Reference/Note 32','cited_quantitative_context','Prior biphasic thiol/precursor ratios below 1, Brust’s 10–30 Å Au particles with final thiol/Au =1:3, and Leff’s precursor ratios 1:1–6:1 are cited to justify excess thiol in the current study. These are distinct reported quantities/denominators, not current Ag reaction ratios.',disposition='retain_cited_context_only')
